// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // admin is the deployer (this test contract); call as admin so onlyAdmin passes
        vm.prank(address(this));
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.setOwner.selector, newOwner)
        );
        assertTrue(ok && abi.decode(ret, (bool)), "admin setOwner must return true");
    }
}
